#!/usr/bin/env python3
"""Generates src/parsers/entities.ts from the HTML Standard's entities.json.
Usage: python3 scripts/gen/entities.py path/to/entities.json
The source file is the WHATWG list (https://html.spec.whatwg.org/entities.json), 2,231 names."""
import json, sys

src = json.load(open(sys.argv[1], encoding="utf-8"))
names = sorted(k[1:] for k in src)  # drop the leading "&"
lines = [
    "// Generated by scripts/gen/entities.py from the HTML Standard's entities.json (2,231 names). Do not edit by hand.",
    "// A name keeps its trailing semicolon; the 106 legacy names also appear without one, as the standard lists them.",
    "export const NAMED_REFERENCES: Record<string, string> = {",
]
for n in names:
    lines.append(f"  {json.dumps(n)}: {json.dumps(src['&' + n]['characters'], ensure_ascii=True)},")
lines.append("};")
lines.append(f"export const LONGEST_REFERENCE = {max(len(n) for n in names)};")
open("src/parsers/entities.ts", "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(len(names), "names")
